SELECT f.A_STOCKSNAME AS `股票简称`, f.A_STOCKCODE AS `股票代码`, f.FORE_CLS AS `业绩预告类型`, ROUND(f.MIN_VAL, 1) AS `归母净利润预测下限(万)`, ROUND(f.MAX_VAL, 1) AS `归母净利润预测上限(万)`, DATE_FORMAT(f.ENDDATE, '%Y-%m-%d') AS `报告期截止日`, DATE_FORMAT(f.DECLAREDATE, '%Y-%m-%d') AS `预告发布日期`, f.SUMMARY AS `业绩预告摘要` FROM STK_ACHIEVE_FORECAST f WHERE f.ISVALID = 1 AND f.A_STOCKSNAME LIKE '%紫金矿业%' AND f.A_STOCKCODE IS NOT NULL AND f.ENDDATE = '2025-06-30 00:00:00.000' AND f.DECLAREDATE IS NOT NULL AND f.DECLAREDATE = (SELECT MAX(DECLAREDATE) FROM STK_ACHIEVE_FORECAST WHERE ISVALID = 1 AND A_STOCKSNAME LIKE '%紫金矿业%' AND A_STOCKCODE IS NOT NULL AND ENDDATE = '2025-06-30 00:00:00.000' AND DECLAREDATE IS NOT NULL) ORDER BY f.DECLAREDATE DESC LIMIT 1;
